import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { NumberInput } from "../number-input";

const dualNumberInputVariants = cva(
    "flex items-center bg-[color-mix(in_srgb,var(--border)_60%,transparent)] rounded-sm overflow-hidden border border-border hover:border-muted-foreground focus-within:border-ring transition-colors",
    {
        variants: {
            size: {
                sm: "h-8",
                default: "h-12",
                lg: "h-14",
            },
        },
        defaultVariants: {
            size: "default",
        },
    }
);

const dualNumberInputLabelVariants = cva(
    "text-muted-foreground font-medium shrink-0",
    {
        variants: {
            size: {
                sm: "text-11 mr-1.5",
                default: "text-13 mr-2",
                lg: "text-14 mr-2.5",
            },
        },
        defaultVariants: {
            size: "default",
        },
    }
);

const dualNumberInputTextVariants = cva(
    "flex-1 min-w-0 bg-transparent font-medium text-foreground overflow-hidden text-ellipsis",
    {
        variants: {
            size: {
                sm: "text-12",
                default: "text-14",
                lg: "text-16",
            },
        },
        defaultVariants: {
            size: "default",
        },
    }
);

const dualNumberInputDividerVariants = cva("w-px bg-border", {
    variants: {
        size: {
            sm: "h-4",
            default: "h-6",
            lg: "h-8",
        },
    },
    defaultVariants: {
        size: "default",
    },
});

const dualNumberInputContainerVariants = cva(
    "flex items-center flex-1 h-full min-w-0",
    {
        variants: {
            size: {
                sm: "px-2",
                default: "px-3",
                lg: "px-4",
            },
        },
        defaultVariants: {
            size: "default",
        },
    }
);

export interface DualNumberInputProps
    extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof dualNumberInputVariants> {
    /**
     * First value (e.g., width)
     */
    value1: number;
    /**
     * Second value (e.g., height)
     */
    value2: number;
    /**
     * Callback when first value changes
     */
    onChange1: (value: number) => void;
    /**
     * Callback when second value changes
     */
    onChange2: (value: number) => void;
    /**
     * Label for first input (e.g., "W")
     */
    label1?: string;
    /**
     * Label for second input (e.g., "H")
     */
    label2?: string;
    /**
     * Minimum value for both inputs
     */
    min?: number;
    /**
     * Maximum value for both inputs
     */
    max?: number;
    /**
     * Step increment for both inputs
     */
    step?: number;
    /**
     * Unit suffix to display after the number (e.g., "px", "s", "%")
     */
    suffix?: string;
    /**
     * Number of decimal places to show
     */
    decimals?: number;
    /**
     * Sensitivity multiplier for drag changes (default: 0.5)
     */
    dragSensitivity?: number;
    /**
     * Disabled state
     */
    disabled?: boolean;
}

/**
 * DualNumberInput - A combined input for two related numeric values
 *
 * Perfect for width/height, X/Y coordinates, or any paired numeric values.
 * Each input supports drag-to-change and direct editing.
 *
 * @example
 * ```tsx
 * <DualNumberInput
 *   value1={width}
 *   value2={height}
 *   onChange1={setWidth}
 *   onChange2={setHeight}
 *   label1="W"
 *   label2="H"
 * />
 * ```
 */
export const DualNumberInput = React.forwardRef<
    HTMLDivElement,
    DualNumberInputProps
>(
    (
        {
            value1,
            value2,
            onChange1,
            onChange2,
            label1 = "X",
            label2 = "Y",
            min,
            max,
            step = 1,
            suffix = "",
            decimals,
            dragSensitivity = 0.5,
            disabled,
            size = "default",
            className,
            ...props
        },
        ref
    ) => {
        return (
            <div
                ref={ref}
                className={cn(
                    dualNumberInputVariants({ size }),
                    disabled && "opacity-50 cursor-not-allowed",
                    className
                )}
                {...props}
            >
                <div className={dualNumberInputContainerVariants({ size })}>
                    <span className={dualNumberInputLabelVariants({ size })}>
                        {label1}
                    </span>
                    <NumberInput
                        value={value1}
                        onChange={onChange1}
                        min={min}
                        max={max}
                        step={step}
                        suffix={suffix}
                        decimals={decimals}
                        dragSensitivity={dragSensitivity}
                        disabled={disabled}
                        variant="borderless"
                        align="left"
                        className={dualNumberInputTextVariants({ size })}
                    />
                </div>
                <div className={dualNumberInputDividerVariants({ size })} />
                <div className={dualNumberInputContainerVariants({ size })}>
                    <span className={dualNumberInputLabelVariants({ size })}>
                        {label2}
                    </span>
                    <NumberInput
                        value={value2}
                        onChange={onChange2}
                        min={min}
                        max={max}
                        step={step}
                        suffix={suffix}
                        decimals={decimals}
                        dragSensitivity={dragSensitivity}
                        disabled={disabled}
                        variant="borderless"
                        align="left"
                        className={dualNumberInputTextVariants({ size })}
                    />
                </div>
            </div>
        );
    }
);

DualNumberInput.displayName = "DualNumberInput";
