import * as React from "react";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio } from "@base-ui/react/radio";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const radioGroupVariants = cva("grid gap-2", {
  variants: {
    orientation: {
      vertical: "grid-flow-row",
      horizontal: "grid-flow-col auto-cols-max gap-4",
    },
  },
  defaultVariants: {
    orientation: "vertical",
  },
});

const radioGroupItemVariants = cva(
  "relative inline-flex shrink-0 items-center justify-center aspect-square rounded-full border-2 ring-offset-background transition-all focus:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-checked:border-primary data-unchecked:border-input",
  {
    variants: {
      size: {
        xs: "h-3 w-3",
        sm: "h-3.5 w-3.5",
        default: "h-4 w-4",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
);

const radioGroupIndicatorVariants = cva(
  "absolute inset-0 flex items-center justify-center",
  {
  variants: {
    size: {
      xs: "",
      sm: "",
      default: "",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

const radioGroupDotVariants = cva(
  "absolute left-1/2 top-1/2 aspect-square -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary transition-transform origin-center data-unchecked:scale-0 data-checked:scale-100",
  {
    variants: {
      size: {
        xs: "h-1 w-1",
        sm: "h-1.5 w-1.5",
        default: "h-2 w-2",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
);

export interface RadioGroupProps
  extends Omit<
      React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive>,
      "orientation" | "onValueChange"
    >,
    VariantProps<typeof radioGroupVariants> {
  /**
   * The orientation of the radio group.
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";

  /**
   * Callback fired when the value changes.
   */
  onValueChange?: (value: string) => void;
}

/**
 * RadioGroup component for single selection from multiple options
 * Built on Base UI Radio Group for full accessibility
 *
 * @example
 * ```tsx
 * <RadioGroup defaultValue="option1">
 *   <div className="flex items-center gap-2">
 *     <RadioGroupItem value="option1" id="r1" />
 *     <label htmlFor="r1">Option 1</label>
 *   </div>
 *   <div className="flex items-center gap-2">
 *     <RadioGroupItem value="option2" id="r2" />
 *     <label htmlFor="r2">Option 2</label>
 *   </div>
 * </RadioGroup>
 * ```
 */
const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(
  ({ className, orientation, onValueChange, ...props }, ref) => {
    return (
      <RadioGroupPrimitive
        className={cn(radioGroupVariants({ orientation, className }))}
        onValueChange={
          onValueChange ? (value: string) => onValueChange(value) : undefined
        }
        {...props}
        ref={ref}
      />
    );
  }
);
RadioGroup.displayName = "RadioGroup";

export interface RadioGroupItemProps
  extends React.ComponentPropsWithoutRef<typeof Radio.Root>,
    VariantProps<typeof radioGroupItemVariants> {
  /**
   * The size of the radio button.
   * @default "default"
   */
  size?: "xs" | "sm" | "default";
}

/**
 * RadioGroupItem component representing a single radio option
 * Must be used within a RadioGroup component
 *
 * @example
 * ```tsx
 * <RadioGroupItem value="option1" id="r1" size="sm" />
 * ```
 */
const RadioGroupItem = React.forwardRef<HTMLElement, RadioGroupItemProps>(
  ({ className, size, ...props }, ref) => {
    return (
      <Radio.Root
        ref={ref}
        className={cn(radioGroupItemVariants({ size, className }))}
        {...props}
      >
        <Radio.Indicator className={cn(radioGroupIndicatorVariants({ size }))}>
          <div className={cn(radioGroupDotVariants({ size }))} />
        </Radio.Indicator>
      </Radio.Root>
    );
  }
);
RadioGroupItem.displayName = "RadioGroupItem";

export { RadioGroup, RadioGroupItem, radioGroupVariants };
