import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const emptyStateVariants = cva(
  "flex flex-col items-center justify-center gap-3 text-center",
  {
    variants: {
      variant: {
        default: "",
        compact: "gap-2",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface EmptyStateProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof emptyStateVariants> {
  /**
   * Optional decorative icon.
   */
  icon?: React.ReactNode;
  /**
   * Primary headline text.
   */
  title?: string;
  /**
   * Supporting description text.
   */
  description?: string;
  /**
   * Optional recovery action (button or link).
   */
  action?: React.ReactNode;
  /**
   * Layout style.
   * @default "default"
   */
  variant?: "default" | "compact";
}

/**
 * Empty state container for no-data and first-run scenarios.
 */
const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(
  ({ className, variant, icon, title, description, action, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(emptyStateVariants({ variant }), className)}
        {...props}
      >
        {icon && (
          <div className="text-muted-foreground">
            {icon}
          </div>
        )}
        {title && (
          <h3 className="text-14 font-medium text-foreground">
            {title}
          </h3>
        )}
        {description && (
          <p className="text-13 text-muted-foreground">
            {description}
          </p>
        )}
        {action && <div className="mt-2">{action}</div>}
        {children}
      </div>
    );
  }
);

EmptyState.displayName = "EmptyState";

export { EmptyState, emptyStateVariants };
