import * as React from "react";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "../../lib/utils";

/**
 * Provider controlling tooltip open delay behavior.
 */
const TooltipProvider = TooltipPrimitive.Provider;

/**
 * Root tooltip state container.
 */
const TooltipRoot = TooltipPrimitive.Root;

/**
 * Trigger element that opens the tooltip.
 */
const TooltipTrigger = TooltipPrimitive.Trigger;

/**
 * Positioned tooltip popup content.
 */
const TooltipContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Popup> & {
    side?: "top" | "right" | "bottom" | "left";
    sideOffset?: number;
  }
>(({ className, side = "top", sideOffset = 4, ...props }, ref) => (
  <TooltipPrimitive.Portal>
    <TooltipPrimitive.Positioner side={side} sideOffset={sideOffset}>
      <TooltipPrimitive.Popup
        ref={ref}
        className={cn(
          "z-50 max-w-[15.625rem] overflow-hidden rounded-md border border-border bg-popover px-3 py-2 text-10 leading-[1.4] text-popover-foreground shadow-md animate-in fade-in-0 zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className
        )}
        {...props}
      />
    </TooltipPrimitive.Positioner>
  </TooltipPrimitive.Portal>
));
TooltipContent.displayName = "TooltipContent";

export interface TooltipProps {
  /**
   * The content to display in the tooltip
   */
  content: React.ReactNode;

  /**
   * The trigger element that will show the tooltip on hover
   */
  children: React.ReactElement;

  /**
   * The preferred side of the trigger to render against when open
   * @default "top"
   */
  side?: "top" | "right" | "bottom" | "left";

  /**
   * The distance in pixels from the trigger
   * @default 4
   */
  sideOffset?: number;

  /**
   * The duration from when the mouse enters the trigger until the tooltip opens
   * @default 300
   */
  delayDuration?: number;

  /**
   * Whether the tooltip should be open by default
   * @default false
   */
  defaultOpen?: boolean;

  /**
   * The controlled open state of the tooltip
   */
  open?: boolean;

  /**
   * Event handler called when the open state changes
   */
  onOpenChange?: (open: boolean) => void;
}

/**
 * Tooltip component for displaying contextual information
 * Built on Base UI Tooltip for full accessibility
 *
 * @example
 * ```tsx
 * <Tooltip content="This is a helpful tooltip">
 *   <button>Hover me</button>
 * </Tooltip>
 * ```
 *
 * @example
 * ```tsx
 * <Tooltip content="Bottom tooltip" side="bottom" delayDuration={500}>
 *   <span>Hover for info</span>
 * </Tooltip>
 * ```
 */
const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  side = "top",
  sideOffset = 4,
  delayDuration = 300,
  defaultOpen = false,
  open,
  onOpenChange,
}) => {
  return (
    <TooltipProvider delay={delayDuration}>
      <TooltipRoot
        defaultOpen={defaultOpen}
        open={open}
        onOpenChange={onOpenChange}
      >
        <TooltipTrigger render={children} />
        <TooltipContent side={side} sideOffset={sideOffset}>
          {content}
        </TooltipContent>
      </TooltipRoot>
    </TooltipProvider>
  );
};
Tooltip.displayName = "Tooltip";

export { Tooltip, TooltipProvider, TooltipRoot, TooltipTrigger, TooltipContent };
