import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Field } from "@base-ui/react/field";
import { cn } from "../../lib/utils";

const inputVariants = cva(
  "flex h-6 w-full rounded-sm border border-input  bg-[color-mix(in_srgb,var(--border)_60%,transparent)] px-2 py-1 text-14 font-normal leading-normal text-foreground transition-colors file:border-0 file:bg-transparent file:text-14 file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:outline-hidden focus-visible:border-ring disabled:cursor-not-allowed disabled:opacity-50 selection:bg-[color-mix(in_srgb,var(--ring)_50%,transparent)]",
  {
    variants: {
      variant: {
        default: "border-border hover:border-muted-foreground",
        error: "border-destructive focus-visible:border-destructive",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  /**
   * Visual style variant.
   *
   * @default "default"
   */
  variant?: VariantProps<typeof inputVariants>["variant"];
}

/**
 * Input component for text input
 *
 * @example
 * ```tsx
 * <Input type="text" placeholder="Enter value" />
 * <Input variant="error" />
 * <Input disabled />
 * ```
 */
const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, variant, type, ...props }, ref) => {
    return (
      <Field.Control
        render={<input type={type} />}
        className={cn(inputVariants({ variant, className }))}
        aria-invalid={variant === "error" || undefined}
        ref={ref}
        {...props}
      />
    );
  }
);
Input.displayName = "Input";

export { Input, inputVariants };
