import * as React from "react";
import { Tabs } from "@base-ui/react/tabs";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

export interface TabsRootProps extends React.ComponentPropsWithoutRef<typeof Tabs.Root> {}

/**
 * Root tab state container.
 */
const TabsRoot = Tabs.Root;

/**
 * Container for tab triggers.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof Tabs.List>
>(({ className, ...props }, ref) => (
  <Tabs.List
    ref={ref}
    className={cn(
      "inline-flex items-center gap-0",
      className
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

const tabsTriggerVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap font-normal transition-all border-b-2 border-transparent text-muted-foreground hover:text-foreground data-active:border-primary data-active:text-foreground focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      size: {
        sm: "px-1.5 pb-1 text-11",
        default: "px-3 pb-2 text-14",
      },
    },
    defaultVariants: {
      size: "sm",
    },
  }
);

export interface TabsTriggerProps
  extends React.ComponentPropsWithoutRef<typeof Tabs.Tab>,
    VariantProps<typeof tabsTriggerVariants> {
  /**
   * Visual size scale for tab trigger labels.
   * @default "sm"
   */
  size?: "sm" | "default";
}

/**
 * Individual tab trigger button.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  TabsTriggerProps
>(({ className, size, ...props }, ref) => (
  <Tabs.Tab
    ref={ref}
    className={cn(tabsTriggerVariants({ size, className }))}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/**
 * Panel content rendered for a selected tab.
 */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof Tabs.Panel>
>(({ className, ...props }, ref) => (
  <Tabs.Panel
    ref={ref}
    className={cn(
      "mt-2 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
      className
    )}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { TabsRoot, TabsList, TabsTrigger, TabsContent };
