import * as React from "react";
import { Menu } from "@base-ui/react/menu";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { Separator } from "../separator/separator";

/**
 * Root menu state container.
 */
const DropdownRoot = Menu.Root;
/**
 * Trigger element that opens the dropdown.
 */
const DropdownTrigger = Menu.Trigger;
/**
 * Group wrapper for related menu items.
 */
const DropdownGroup = Menu.Group;
/**
 * Portal root for rendering dropdown overlays.
 */
const DropdownPortal = Menu.Portal;

/**
 * Positioned dropdown content popup.
 */
const DropdownContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof Menu.Popup> & {
    sideOffset?: number;
    side?: "top" | "right" | "bottom" | "left";
    align?: "start" | "center" | "end";
  }
>(({ className, sideOffset = 4, side, align, ...props }, ref) => (
  <DropdownPortal>
    <Menu.Positioner sideOffset={sideOffset} side={side} align={align}>
      <Menu.Popup
        ref={ref}
        className={cn(
          "z-50 min-w-32 overflow-hidden rounded-sm border border-border bg-popover p-2 text-popover-foreground shadow-lg",
          "data-open:animate-in data-closed:animate-out",
          "data-closed:fade-out-0 data-open:fade-in-0",
          "data-closed:zoom-out-95 data-open:zoom-in-95",
          "data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2",
          "data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
          className
        )}
        {...props}
      />
    </Menu.Positioner>
  </DropdownPortal>
));
DropdownContent.displayName = "DropdownContent";

/**
 * Visual variants for dropdown items.
 */
const dropdownItemVariants = cva(
  "relative flex h-6 w-full cursor-pointer select-none items-center gap-2 rounded px-2 outline-hidden transition-colors mb-1 last:mb-0 data-highlighted:bg-[color-mix(in_srgb,var(--secondary)_30%,transparent)] data-disabled:pointer-events-none data-disabled:opacity-50 [&>svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "text-12 font-normal",
        destructive: "font-normal text-destructive text-12 data-highlighted:bg-[color-mix(in_srgb,var(--destructive)_10%,transparent)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface DropdownItemProps
  extends Omit<React.ComponentPropsWithoutRef<typeof Menu.Item>, "onSelect">,
    VariantProps<typeof dropdownItemVariants> {
  /**
   * Callback fired when the item is selected.
   * Maps to onClick internally for Base UI compatibility.
   */
  onSelect?: (event: React.MouseEvent<HTMLDivElement>) => void;
}

const DropdownItem = React.forwardRef<
  HTMLDivElement,
  DropdownItemProps
>(({ className, variant, onSelect, onClick, ...props }, ref) => (
  <Menu.Item
    ref={ref}
    className={cn(dropdownItemVariants({ variant }), className)}
    onClick={(event: React.MouseEvent<HTMLDivElement>) => {
      onClick?.(event);
      onSelect?.(event);
    }}
    {...props}
  />
));
DropdownItem.displayName = "DropdownItem";

/**
 * Non-interactive text label inside dropdown content.
 */
const DropdownLabel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("w-full px-2 py-1 text-12 font-semibold", className)}
    {...props}
  />
));
DropdownLabel.displayName = "DropdownLabel";

const DropdownSeparator = Separator;
DropdownSeparator.displayName = "DropdownSeparator";

export {
  DropdownRoot,
  DropdownTrigger,
  DropdownPortal,
  DropdownContent,
  DropdownGroup,
  DropdownLabel,
  DropdownItem,
  DropdownSeparator,
  dropdownItemVariants,
};
