import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Mic, Paperclip, Square, ArrowUp, Sparkles, Loader2 } from "lucide-react";
import { cn } from "../../lib/utils";
import { Button } from "../button";

const aiPromptInputVariants = cva(
    "flex flex-col w-full rounded-xl border border-border bg-card p-3 shadow-xs transition-all focus-within:ring-1 focus-within:ring-ring",
    {
        variants: {
            variant: {
                default: "",
            },
            size: {
                default: "",
                sm: "p-2",
            },
        },
        defaultVariants: {
            variant: "default",
            size: "default",
        },
    }
);

export interface AIPromptInputProps
    extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof aiPromptInputVariants> {
    value?: string;
    onChange?: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
    onSubmit?: () => void;
    onStop?: () => void;
    onAttach?: () => void;
    onOptimize?: () => void;
    attachments?: React.ReactNode;
    isGenerating?: boolean;
    isOptimizing?: boolean;
    placeholder?: string;
    showAttach?: boolean;
    showMic?: boolean;
}

const AIPromptInput = React.forwardRef<HTMLDivElement, AIPromptInputProps>(
    ({ className, variant, size, value, onChange, onSubmit, onStop, onAttach, onOptimize, attachments, isGenerating, isOptimizing, placeholder, showAttach = true, showMic = true, ...props }, ref) => {
        const textareaRef = React.useRef<HTMLTextAreaElement>(null);

        // Auto-resize textarea
        React.useEffect(() => {
            if (textareaRef.current) {
                textareaRef.current.style.height = "auto";
                textareaRef.current.style.height = textareaRef.current.scrollHeight + "px";
            }
        }, [value]);

        const buttonSizeClass = size === "sm" ? "h-6 w-6" : "h-8 w-8";
        const iconSizeClass = size === "sm" ? "h-3.5 w-3.5" : "h-4 w-4";

        return (
            <div
                ref={ref}
                className={cn(aiPromptInputVariants({ variant, size, className }))}
                {...props}
            >
                {attachments && (
                    <div className="mb-2 flex flex-wrap gap-2">
                        {attachments}
                    </div>
                )}
                <textarea
                    ref={textareaRef}
                    value={value}
                    onChange={onChange}
                    placeholder={placeholder || "Describe your vector..."}
                    className={cn(
                        "flex w-full resize-none bg-transparent px-1 py-1 text-sm placeholder:text-muted-foreground focus-visible:outline-hidden disabled:cursor-not-allowed disabled:opacity-50",
                        size === "sm" ? "min-h-[2rem] text-xs" : "min-h-[2.5rem]"
                    )}
                    rows={1}
                />
                <div className="mt-2 flex items-center justify-between">
                    <div className="flex items-center gap-1">
                        {showAttach && (
                            <Button 
                                variant="ghost" 
                                size="sm" 
                                className="h-6 px-2 text-xs text-muted-foreground hover:bg-accent hover:text-foreground gap-1.5"
                                onClick={onAttach}
                            >
                                <Paperclip className="h-3.5 w-3.5" />
                                Scene
                            </Button>
                        )}
                        {onOptimize && (
                            <Button 
                                variant="ghost" 
                                size="sm" 
                                className="h-6 px-2 text-xs text-muted-foreground hover:bg-accent hover:text-foreground gap-1.5"
                                onClick={onOptimize}
                                disabled={isOptimizing}
                            >
                                {isOptimizing ? (
                                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                                ) : (
                                    <Sparkles className="h-3.5 w-3.5" />
                                )}
                                Optimize
                            </Button>
                        )}
                        {showMic && (
                            <Button variant="ghost" size="icon" className={cn(buttonSizeClass, "text-muted-foreground hover:bg-accent hover:text-foreground")}>
                                <Mic className={iconSizeClass} />
                            </Button>
                        )}
                    </div>
                    <div>
                        {isGenerating ? (
                            <Button
                                variant="secondary"
                                size="icon"
                                onClick={onStop}
                                className={cn(buttonSizeClass, "rounded-full bg-secondary hover:bg-[color-mix(in_srgb,var(--secondary)_80%,transparent)]")}
                            >
                                <Square className="h-3 w-3 fill-current" />
                            </Button>
                        ) : (
                            <Button
                                variant="default"
                                size="icon"
                                onClick={onSubmit}
                                className={cn(buttonSizeClass, "rounded-full")}
                            >
                                <ArrowUp className={iconSizeClass} />
                            </Button>
                        )}
                    </div>
                </div>
            </div>
        );
    }
);
AIPromptInput.displayName = "AIPromptInput";

export { AIPromptInput, aiPromptInputVariants };
