import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Search, X } from "lucide-react";
import { cn } from "../../lib/utils";

const searchInputVariants = cva(
  "flex h-6 w-full rounded-sm border bg-[color-mix(in_srgb,var(--border)_60%,transparent)] px-3 py-1 text-13 text-foreground transition-colors file:border-0 file:bg-transparent file:text-13 file:font-medium placeholder:text-muted-foreground focus-visible:outline-hidden disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "border-border hover:border-muted-foreground focus-visible:border-ring",
        error: "border-destructive focus-visible:border-destructive",
      },
      size: {
        sm: "h-6 text-11 px-3",
        default: "h-6 text-13 px-3",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface SearchBarProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size">,
  VariantProps<typeof searchInputVariants> {
  /**
   * Fired when a search should be executed.
   */
  onSearch?: (query: string) => void;
  /**
   * Fired when clear action is triggered.
   */
  onClear?: () => void;
  /**
   * Debounce delay for `onSearch` in milliseconds.
   * Set to `0` for immediate search.
   * @default 300
   */
  debounceMs?: number;
  /**
   * Whether the clear button is shown when input has value.
   * @default true
   */
  clearable?: boolean;
  /**
   * Candidate suggestion values.
   */
  suggestions?: string[];
  /**
   * Fired when suggestion is selected.
   */
  onSuggestionSelect?: (suggestion: string) => void;
  /**
   * Enables the suggestions popover.
   * @default false
   */
  showSuggestions?: boolean;
  /**
   * Visual style of the input.
   * @default "default"
   */
  variant?: "default" | "error";
  /**
   * Compact size scale.
   * @default "default"
   */
  size?: "sm" | "default";
}

/**
 * Search input with optional debounce, clear action, and suggestions.
 */
const SearchBar = React.forwardRef<HTMLInputElement, SearchBarProps>(
  (
    {
      className,
      variant,
      size,
      onSearch,
      onClear,
      debounceMs = 300,
      clearable = true,
      suggestions = [],
      onSuggestionSelect,
      showSuggestions = false,
      value: controlledValue,
      onChange,
      onFocus,
      onBlur,
      placeholder = "Search...",
      style,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = React.useState(controlledValue || "");
    const [isFocused, setIsFocused] = React.useState(false);
    const [showResults, setShowResults] = React.useState(false);
    const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    // Sync internal value with controlled value
    React.useEffect(() => {
      if (controlledValue !== undefined) {
        setInternalValue(String(controlledValue));
      }
    }, [controlledValue]);

    // Debounced search
    React.useEffect(() => {
      if (!onSearch || debounceMs <= 0) return;

      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      timeoutRef.current = setTimeout(() => {
        onSearch(String(internalValue));
      }, debounceMs);

      return () => {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
      };
    }, [internalValue, onSearch, debounceMs]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newValue = e.target.value;
      setInternalValue(newValue);

      if (onChange) {
        onChange(e);
      }

      // Immediate search if no debounce
      if (onSearch && debounceMs <= 0) {
        onSearch(newValue);
      }

      // Show suggestions when typing
      if (showSuggestions && newValue.length > 0) {
        setShowResults(true);
      } else {
        setShowResults(false);
      }
    };

    const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
      setIsFocused(true);

      if (onFocus) {
        onFocus(e);
      }

      // Show suggestions on focus if there's a value
      if (showSuggestions && String(internalValue).length > 0) {
        setShowResults(true);
      }
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      // Delay hiding results to allow for suggestion clicks
      setTimeout(() => {
        setIsFocused(false);
        setShowResults(false);
      }, 150);

      if (onBlur) {
        onBlur(e);
      }
    };

    const handleClear = () => {
      setInternalValue("");
      setShowResults(false);

      if (onClear) {
        onClear();
      }

      if (onSearch) {
        onSearch("");
      }
    };

    const handleSuggestionSelect = (suggestion: string) => {
      setInternalValue(suggestion);
      setShowResults(false);

      if (onSuggestionSelect) {
        onSuggestionSelect(suggestion);
      }

      if (onSearch) {
        onSearch(suggestion);
      }
    };

    const filteredSuggestions = suggestions.filter((suggestion) =>
      suggestion.toLowerCase().includes(String(internalValue).toLowerCase())
    );

    const hasValue = String(internalValue).length > 0;
    const showClearButton = clearable && hasValue;
    const shouldShowResults = showResults && isFocused && showSuggestions && hasValue;
    const inputStyle: React.CSSProperties = {
      paddingLeft: "2.25rem",
      ...(showClearButton ? { paddingRight: "2rem" } : null),
      ...style,
    };

    return (
      <div className={cn("relative w-full", className)}>
        <div className="relative">
          <Search
            className={cn(
              "pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground transition-colors",
              isFocused && "text-primary"
            )}
          />
          <input
            ref={ref}
            value={internalValue}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            placeholder={placeholder}
            aria-invalid={variant === "error" || undefined}
            style={inputStyle}
            className={searchInputVariants({ variant, size })}
            {...props}
          />
          {showClearButton && (
            <button
              type="button"
              onClick={handleClear}
              className="absolute right-2 top-1/2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          )}
        </div>

        {shouldShowResults && filteredSuggestions.length > 0 && (
          <div className="absolute top-full z-50 mt-1 w-full rounded-md border border-border bg-popover p-1 shadow-md">
            {filteredSuggestions.map((suggestion, index) => (
              <button
                key={index}
                type="button"
                onClick={() => handleSuggestionSelect(suggestion)}
                className="w-full cursor-pointer rounded-sm px-2 py-1.5 text-left text-13 text-popover-foreground transition-colors hover:bg-accent focus-visible:bg-accent focus-visible:outline-hidden"
              >
                {suggestion}
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }
);

SearchBar.displayName = "SearchBar";

export { SearchBar, searchInputVariants };
