import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const labelVariants = cva(
  "peer-disabled:cursor-not-allowed peer-disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "text-14 font-medium leading-snug text-foreground",
        title: "text-12 font-medium leading-snug text-muted-foreground block",
        inline: "text-14 font-normal leading-snug text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface LabelProps
  extends React.LabelHTMLAttributes<HTMLLabelElement>,
    VariantProps<typeof labelVariants> {
  /**
   * Visual presentation of the label.
   * @default "default"
   */
  variant?: "default" | "title" | "inline";
}

/**
 * Label component for form inputs
 *
 * Variants:
 * - `default`: Standard label for form inputs
 * - `title`: Section/field title label (matches StyledLabelTitle from plugins)
 * - `inline`: Inline label for radio buttons, checkboxes, etc.
 *
 * @example
 * ```tsx
 * // Standard form label
 * <Label htmlFor="email">Email</Label>
 * <Input id="email" />
 *
 * // Section title (matches your StyledLabelTitle)
 * <Label variant="title">Scale</Label>
 * <Input />
 *
 * // Inline with radio/checkbox
 * <Label variant="inline">
 *   <input type="radio" />
 *   Option 1
 * </Label>
 * ```
 */
const Label = React.forwardRef<
  HTMLLabelElement,
  LabelProps
>(({ className, variant, onMouseDown, ...props }, ref) => (
  <label
    ref={ref}
    className={cn(labelVariants({ variant, className }))}
    onMouseDown={(event) => {
      onMouseDown?.(event);
      // Prevent text selection on double-click (matches Radix Label behavior)
      if (!event.defaultPrevented && event.detail > 1) {
        event.preventDefault();
      }
    }}
    {...props}
  />
));
Label.displayName = "Label";

export { Label, labelVariants };
