import * as React from "react";
import { motion } from "framer-motion";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const segmentedControlVariants = cva(
  "relative flex items-stretch justify-stretch rounded-md p-0.5",
  {
    variants: {
      variant: {
        default: "bg-muted",
        outline: "bg-transparent border border-input p-px",
      },
      size: {
        sm: "h-6",
        default: "h-6",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

const segmentItemVariants = cva(
  "relative z-10 flex flex-1 cursor-pointer items-center justify-center rounded px-1 transition-colors",
  {
    variants: {
      variant: {
        default: "",
        outline: "",
      },
      active: {
        true: "",
        false: "text-muted-foreground hover:text-foreground",
      },
    },
    compoundVariants: [
      {
        variant: "default",
        active: true,
        class: "text-primary-foreground",
      },
      {
        variant: "outline",
        active: true,
        class: "text-foreground",
      },
    ],
    defaultVariants: {
      variant: "default",
      active: false,
    },
  }
);

const segmentTextVariants = cva(
  "whitespace-nowrap text-center text-11 leading-tight tracking-tight",
  {
    variants: {
      active: {
        true: "font-semibold",
        false: "font-normal",
      },
    },
    defaultVariants: {
      active: false,
    },
  }
);

export interface SegmentOption {
  value: string;
  label: string;
}

export interface SegmentedControlProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
  VariantProps<typeof segmentedControlVariants> {
  /**
   * The currently selected value.
   */
  value: string;

  /**
   * Array of options to display.
   */
  options: SegmentOption[];

  /**
   * Callback fired when the value changes.
   */
  onChange: (value: string) => void;

  /**
   * Whether the control is disabled.
   */
  disabled?: boolean;

  /**
   * The visual variant of the segmented control.
   * @default "default"
   */
  variant?: "default" | "outline";

  /**
   * The size of the segmented control.
   * @default "default"
   */
  size?: "sm" | "default";
}

/**
 * Segmented control component with animated sliding background
 * Multi-option selector with smooth spring animations
 *
 * @example
 * ```tsx
 * const [view, setView] = useState("grid");
 *
 * <SegmentedControl
 *   value={view}
 *   options={[
 *     { value: "grid", label: "Grid" },
 *     { value: "list", label: "List" },
 *   ]}
 *   onChange={setView}
 * />
 * ```
 */
const SegmentedControl = React.forwardRef<HTMLDivElement, SegmentedControlProps>(
  (
    {
      className,
      variant = "default",
      size,
      value,
      options,
      onChange,
      disabled = false,
      ...props
    },
    ref
  ) => {
    const containerRef = React.useRef<HTMLDivElement>(null);
    const [itemRects, setItemRects] = React.useState<
      { left: number; width: number }[]
    >([]);

    // Update rects when options change or container resizes
    const updateRects = React.useCallback(() => {
      if (!containerRef.current) return;
      const rects = Array.from(containerRef.current.children)
        .map((child) => {
          if ((child as HTMLElement).getAttribute("data-segment-item")) {
            const el = child as HTMLElement;
            return {
              left: el.offsetLeft,
              width: el.offsetWidth,
            };
          }
          return { left: 0, width: 0 };
        })
        .filter((rect) => rect.width > 0);
      setItemRects(rects);
    }, []);

    React.useEffect(() => {
      updateRects();
    }, [options, updateRects]);

    // Add resize observer to update rects when container size changes
    React.useEffect(() => {
      const resizeObserver = new ResizeObserver(() => {
        updateRects();
      });

      if (containerRef.current) {
        resizeObserver.observe(containerRef.current);
      }

      return () => {
        resizeObserver.disconnect();
      };
    }, [updateRects]);

    const activeIndex = options.findIndex((o) => o.value === value);
    const activeRect = itemRects[activeIndex];

    return (
      <div
        ref={ref}
        className={cn(segmentedControlVariants({ variant, size, className }))}
        role="group"
        {...props}
      >
        <div ref={containerRef} className="relative flex w-full">
          {activeRect && (
            <motion.div
              className={cn(
                "absolute z-0 rounded",
                size === "sm" ? "h-5" : "h-5",
                variant === "default" ? "bg-primary shadow-xs" : "bg-muted"
              )}
              initial={false}
              animate={{
                x: activeRect.left,
                width: activeRect.width,
              }}
              style={{
                top: 0,
                left: 0,
              }}
              transition={{
                type: "spring",
                stiffness: 400,
                damping: 30,
                x: { type: "spring", stiffness: 400, damping: 30 },
                width: { type: "spring", stiffness: 400, damping: 30 },
              }}
            />
          )}
          {options.map((option) => {
            const isActive = value === option.value;
            return (
              <button
                key={option.value}
                type="button"
                data-segment-item="true"
                onClick={() => !disabled && onChange(option.value)}
                disabled={disabled}
                className={cn(
                  segmentItemVariants({ variant, active: isActive }),
                  disabled && "cursor-not-allowed opacity-50"
                )}
                role="radio"
                aria-checked={isActive}
                aria-label={option.label}
              >
                <span className={cn(segmentTextVariants({ active: isActive }))}>
                  {option.label}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    );
  }
);

SegmentedControl.displayName = "SegmentedControl";

export { SegmentedControl, segmentedControlVariants };
