import * as React from "react";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const checkboxVariants = cva(
  "peer inline-flex shrink-0 cursor-pointer items-center justify-center rounded border-2 transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "data-checked:bg-primary data-checked:border-primary data-unchecked:bg-background data-unchecked:border-input",
        error: "data-checked:bg-destructive data-checked:border-destructive data-unchecked:bg-[color-mix(in_srgb,var(--destructive)_10%,transparent)] data-unchecked:border-destructive",
      },
      size: {
        xs: "h-3.5 w-3.5",
        sm: "h-4 w-4",
        default: "h-5 w-5",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

const checkboxIconVariants = cva(
  "block text-primary-foreground transition-opacity",
  {
    variants: {
      variant: {
        default: "",
        error: "",
      },
      size: {
        xs: "h-2 w-2",
        sm: "h-2.5 w-2.5",
        default: "h-3 w-3",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

// Checkmark icon component
const CheckIcon = ({ className }: { className?: string }) => (
  <svg
    viewBox="0 0 12 12"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
  >
    <path
      d="M10 3L4.5 8.5L2 6"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

export interface CheckboxProps
  extends Omit<
      React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>,
      "checked" | "defaultChecked" | "onCheckedChange"
    >,
    VariantProps<typeof checkboxVariants> {
  /**
   * The controlled checked state of the checkbox.
   */
  checked?: boolean;

  /**
   * The default checked state when uncontrolled.
   */
  defaultChecked?: boolean;

  /**
   * Callback fired when the checked state changes.
   */
  onCheckedChange?: (checked: boolean) => void;

  /**
   * Whether the checkbox is disabled.
   */
  disabled?: boolean;

  /**
   * The visual variant of the checkbox.
   * @default "default"
   */
  variant?: "default" | "error";

  /**
   * The size of the checkbox.
   * @default "default"
   */
  size?: "xs" | "sm" | "default";

  /**
   * Optional aria-label for accessibility.
   * Required if no visible label is provided.
   */
  "aria-label"?: string;
}

/**
 * Checkbox component with checkmark indicator
 * Built on Base UI Checkbox for full accessibility (role="checkbox")
 *
 * @example
 * ```tsx
 * // Uncontrolled
 * <Checkbox defaultChecked aria-label="Accept terms" />
 *
 * // Controlled
 * <Checkbox
 *   checked={accepted}
 *   onCheckedChange={setAccepted}
 *   aria-label="Accept terms"
 * />
 *
 * // Error state
 * <Checkbox variant="error" aria-label="Invalid option" />
 * ```
 */
const Checkbox = React.forwardRef<
  HTMLElement,
  CheckboxProps
>(({ className, variant, size, onCheckedChange, ...props }, ref) => (
  <CheckboxPrimitive.Root
    className={cn(checkboxVariants({ variant, size, className }))}
    aria-invalid={variant === "error" || undefined}
    onCheckedChange={onCheckedChange}
    {...props}
    ref={ref}
  >
    <CheckboxPrimitive.Indicator
      className={cn(
        checkboxIconVariants({ variant, size }),
        "data-unchecked:opacity-0 data-checked:opacity-100"
      )}
    >
      <CheckIcon />
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
));
Checkbox.displayName = "Checkbox";

export { Checkbox, checkboxVariants };
