import * as React from "react";
import { cva } from "class-variance-authority";
import {
  X,
  CheckCircle2,
  AlertCircle,
  Info,
  AlertTriangle,
  Loader2,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "../../lib/utils";

const toastVariants = cva(
  "pointer-events-auto relative flex w-full items-center gap-3 overflow-hidden rounded-lg border-0 bg-[hsl(0_0%_10%)] px-4 py-3 text-white shadow-lg transition-all"
);

interface ToastProps {
  /**
   * Internal toast identifier.
   */
  id: string;
  /**
   * Primary toast message.
   */
  title?: string;
  /**
   * Secondary toast message.
   */
  description?: string;
  /**
   * Auto-dismiss delay in milliseconds.
   * Use `Infinity` for persistent toasts.
   * @default 3000
   */
  duration?: number;
  /**
   * Optional action element rendered inside the toast.
   */
  action?: React.ReactNode;
  /**
   * Close handler provided by the provider.
   */
  onClose: (id: string) => void;
  /**
   * Visual tone of the toast.
   * @default "default"
   */
  variant?: "default" | "success" | "error" | "warning" | "info" | "loading";
}

const Toast = ({
  id,
  title,
  description,
  duration = 3000,
  variant,
  action,
  onClose,
}: ToastProps) => {
  React.useEffect(() => {
    if (duration === Infinity) return;

    const timer = setTimeout(() => {
      onClose(id);
    }, duration);

    return () => clearTimeout(timer);
  }, [id, duration, onClose]);

  const getIcon = () => {
    switch (variant) {
      case "success":
        return (
          <CheckCircle2 className="h-5 w-5 shrink-0 text-[hsl(156_100%_41%)]" />
        );
      case "error":
        return (
          <AlertCircle className="h-5 w-5 shrink-0 text-[hsl(0_100%_63%)]" />
        );
      case "warning":
        return (
          <AlertTriangle className="h-5 w-5 shrink-0 text-[hsl(35_100%_50%)]" />
        );
      case "info":
        return <Info className="h-5 w-5 shrink-0 text-[hsl(211_100%_52%)]" />;
      case "loading":
        return (
          <Loader2 className="h-5 w-5 shrink-0 animate-spin text-[hsl(156_100%_41%)]" />
        );
      default:
        return null;
    }
  };

  return (
    <div className={cn(toastVariants())}>
      {getIcon()}
      <div className="flex-1 min-w-0">
        {title && (
          <div className="text-15 font-normal leading-tight">{title}</div>
        )}
        {description && (
          <div className="text-13 opacity-80 mt-0.5">{description}</div>
        )}
      </div>
      {action && <div className="shrink-0">{action}</div>}
      <button
        onClick={() => onClose(id)}
        className="shrink-0 ml-2 opacity-70 hover:opacity-100 transition-opacity focus:outline-hidden"
      >
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </button>
    </div>
  );
};

// Toast Provider and Context
interface ToastItem extends Omit<ToastProps, "onClose"> {
  /**
   * Stable item identifier for list rendering and dismissal.
   */
  id: string;
}

interface ToastContextValue {
  toasts: ToastItem[];
  toast: (props: Omit<ToastItem, "id">) => string;
  dismiss: (id: string) => void;
}

const ToastContext = React.createContext<ToastContextValue | undefined>(
  undefined
);

export const useToast = () => {
  const context = React.useContext(ToastContext);
  if (!context) {
    throw new Error("useToast must be used within ToastProvider");
  }
  return context;
};

export interface ToastProviderProps {
  /**
   * Provider children.
   */
  children: React.ReactNode;
  /**
   * Maximum number of visible toasts.
   * @default 3
   */
  maxToasts?: number;
  /**
   * Placement of the toast viewport.
   * @default "bottom-right"
   */
  position?:
    | "top-center"
    | "top-right"
    | "bottom-center"
    | "bottom-right"
    | "bottom-left"
    | "top-left";
}

export const ToastProvider = ({
  children,
  maxToasts = 3,
  position = "bottom-right",
}: ToastProviderProps) => {
  const [toasts, setToasts] = React.useState<ToastItem[]>([]);

  const toast = React.useCallback(
    (props: Omit<ToastItem, "id">): string => {
      const id = Math.random().toString(36).substring(2, 9);

      setToasts((prev) => {
        const newToasts = [...prev, { ...props, id }];
        // Limit number of toasts
        if (newToasts.length > maxToasts) {
          return newToasts.slice(-maxToasts);
        }
        return newToasts;
      });

      return id;
    },
    [maxToasts]
  );

  const dismiss = React.useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const value = React.useMemo(
    () => ({ toasts, toast, dismiss }),
    [toasts, toast, dismiss]
  );

  const getPositionClasses = () => {
    switch (position) {
      case "top-center":
        return "top-0 left-1/2 -translate-x-1/2 flex-col items-center md:max-w-[26.25rem]";
      case "top-right":
        return "top-0 right-0 flex-col md:max-w-[26.25rem]";
      case "top-left":
        return "top-0 left-0 flex-col md:max-w-[26.25rem]";
      case "bottom-center":
        return "bottom-0 left-1/2 -translate-x-1/2 flex-col-reverse items-center md:max-w-[26.25rem]";
      case "bottom-left":
        return "bottom-0 left-0 flex-col-reverse md:max-w-[26.25rem]";
      case "bottom-right":
      default:
        return "bottom-0 right-0 flex-col-reverse md:max-w-[26.25rem]";
    }
  };

  const getAnimationDirection = () => {
    if (position.startsWith("top")) {
      return { initial: { y: -50 }, animate: { y: 0 } };
    }
    return { initial: { y: 50 }, animate: { y: 0 } };
  };

  const animationProps = getAnimationDirection();

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div
        className={cn(
          "pointer-events-none fixed z-100 flex max-h-screen w-full gap-2 p-4",
          getPositionClasses()
        )}
      >
        <AnimatePresence mode="popLayout">
          {toasts.map((toastItem) => (
            <motion.div
              key={toastItem.id}
              initial={{ opacity: 0, ...animationProps.initial, scale: 0.3 }}
              animate={{ opacity: 1, ...animationProps.animate, scale: 1 }}
              exit={{ opacity: 0, scale: 0.5, transition: { duration: 0.2 } }}
              transition={{
                type: "spring",
                stiffness: 260,
                damping: 20,
              }}
              layout
            >
              <Toast {...toastItem} onClose={dismiss} />
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </ToastContext.Provider>
  );
};

export { Toast, toastVariants };
export type { ToastProps, ToastItem };
