import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "../../lib/utils";

/**
 * Card size variants type
 */
type CardSize = "default" | "sm" | "xs";

/**
 * Context for sharing size across Card components
 */
const CardContext = React.createContext<CardSize>("default");

/**
 * Card - Main container component
 * Compact card for plugin UIs with subtle border and background
 */
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Shared size scale passed to card sub-components.
   * @default "default"
   */
  size?: CardSize;
}

const Card = React.forwardRef<HTMLDivElement, CardProps>(
  ({ className, size = "default", children, ...props }, ref) => (
    <CardContext.Provider value={size}>
      <div
        ref={ref}
        className={cn(
          "rounded-lg border border-border bg-card text-card-foreground",
          className
        )}
        {...props}
      >
        {children}
      </div>
    </CardContext.Provider>
  )
);
Card.displayName = "Card";

/**
 * CardHeader variants
 */
const cardHeaderVariants = cva("flex flex-col space-y-1", {
  variants: {
    size: {
      default: "p-4",
      sm: "p-3",
      xs: "p-2",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

/**
 * CardHeader - Top section of card
 * Contains title and description with compact spacing for plugins
 */
interface CardHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Overrides inherited card size for this section.
   */
  size?: CardSize;
}

const CardHeader = React.forwardRef<HTMLDivElement, CardHeaderProps>(
  ({ className, size: sizeProp, ...props }, ref) => {
    const contextSize = React.useContext(CardContext);
    const size = sizeProp ?? contextSize;

    return (
      <div
        ref={ref}
        className={cn(cardHeaderVariants({ size }), className)}
        {...props}
      />
    );
  }
);
CardHeader.displayName = "CardHeader";

/**
 * CardTitle variants
 */
const cardTitleVariants = cva("font-medium tracking-tight", {
  variants: {
    size: {
      default: "text-14 leading-snug",
      sm: "text-13 leading-snug",
      xs: "text-12 leading-snug",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

/**
 * CardTitle - Main heading in card header
 * Uses heading typography for plugin UIs
 */
interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /**
   * Overrides inherited card size for this section.
   */
  size?: CardSize;
}

const CardTitle = React.forwardRef<HTMLParagraphElement, CardTitleProps>(
  ({ className, size: sizeProp, ...props }, ref) => {
    const contextSize = React.useContext(CardContext);
    const size = sizeProp ?? contextSize;

    return (
      <h3
        ref={ref}
        className={cn(cardTitleVariants({ size }), className)}
        {...props}
      />
    );
  }
);
CardTitle.displayName = "CardTitle";

/**
 * CardDescription variants
 */
const cardDescriptionVariants = cva(
  "font-normal text-muted-foreground",
  {
    variants: {
      size: {
        default: "text-11 leading-normal",
        sm: "text-10 leading-normal",
        xs: "text-10 leading-normal",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
);

/**
 * CardDescription - Descriptive text in card header
 * Uses body-sm typography with muted color
 */
interface CardDescriptionProps
  extends React.HTMLAttributes<HTMLParagraphElement> {
  /**
   * Overrides inherited card size for this section.
   */
  size?: CardSize;
}

const CardDescription = React.forwardRef<
  HTMLParagraphElement,
  CardDescriptionProps
>(({ className, size: sizeProp, ...props }, ref) => {
  const contextSize = React.useContext(CardContext);
  const size = sizeProp ?? contextSize;

  return (
    <p
      ref={ref}
      className={cn(cardDescriptionVariants({ size }), className)}
      {...props}
    />
  );
});
CardDescription.displayName = "CardDescription";

/**
 * CardContent variants
 */
const cardContentVariants = cva("", {
  variants: {
    size: {
      default: "p-4",
      sm: "p-3",
      xs: "p-2",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

/**
 * CardContent - Main content area of card
 * Compact padding optimized for plugin UIs
 */
interface CardContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Overrides inherited card size for this section.
   */
  size?: CardSize;
}

const CardContent = React.forwardRef<HTMLDivElement, CardContentProps>(
  ({ className, size: sizeProp, ...props }, ref) => {
    const contextSize = React.useContext(CardContext);
    const size = sizeProp ?? contextSize;

    return (
      <div
        ref={ref}
        className={cn(cardContentVariants({ size }), "pt-0", className)}
        {...props}
      />
    );
  }
);
CardContent.displayName = "CardContent";

/**
 * CardFooter variants
 */
const cardFooterVariants = cva("flex items-center", {
  variants: {
    size: {
      default: "p-4",
      sm: "p-3",
      xs: "p-2",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

/**
 * CardFooter - Bottom section of card
 * Typically used for actions or additional info
 */
interface CardFooterProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Overrides inherited card size for this section.
   */
  size?: CardSize;
}

const CardFooter = React.forwardRef<HTMLDivElement, CardFooterProps>(
  ({ className, size: sizeProp, ...props }, ref) => {
    const contextSize = React.useContext(CardContext);
    const size = sizeProp ?? contextSize;

    return (
      <div
        ref={ref}
        className={cn(cardFooterVariants({ size }), "pt-0", className)}
        {...props}
      />
    );
  }
);
CardFooter.displayName = "CardFooter";

export { Card, CardHeader, CardFooter, CardTitle, CardDescription, CardContent };
