const SelectSeparator = Separator;
SelectSeparator.displayName = "SelectSeparator";

export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface SelectSimpleProps {
  /**
   * The controlled value of the select
   */
  value?: string;

  /**
   * The default value when uncontrolled
   */
  defaultValue?: string;

  /**
   * Callback fired when the value changes
   */
  onValueChange?: (value: string) => void;

  /**
   * Array of options to display
   */
  options: SelectOption[];

  /**
   * Placeholder text when no value is selected
   * @default "Select an option"
   */
  placeholder?: string;

  /**
   * Whether the select is disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Additional class name for the trigger
   */
  className?: string;
}

/**
 * Simple Select component for basic dropdown selection
 * Built on Base UI Select for full accessibility
 *
 * @example
 * ```tsx
 * // Uncontrolled
 * <Select
 *   options={[
 *     { value: "1", label: "Option 1" },
 *     { value: "2", label: "Option 2" },
 *   ]}
 *   defaultValue="1"
 * />
 *
 * // Controlled
 * <Select
 *   options={workspaces.map(w => ({ value: w.id, label: w.name }))}
 *   value={selectedWorkspace}
 *   onValueChange={setSelectedWorkspace}
 *   placeholder="Select a workspace"
 * />
 * ```
 */
const SimpleSelect: React.FC<SelectSimpleProps> = ({
  value,
  defaultValue,
  onValueChange,
  options,
  placeholder = "Select an option",
  disabled = false,
  className,
}) => {
  // Keep option values non-empty. Base UI reserves the empty string for "no selection".

  return (
    <SelectRoot
      value={value}
      defaultValue={defaultValue}
      onValueChange={onValueChange ? (val: string | null, _eventDetails: unknown) => { if (val !== null) onValueChange(val); } : undefined}
      disabled={disabled}
    >
      <SelectTrigger className={className}>
        <SelectValue placeholder={placeholder}>
          {(val: string | null) => {
            if (val === null || val === undefined) return null;
            const option = options.find((o) => o.value === val);
            return option?.label ?? val;
          }}
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem
            key={option.value}
            value={option.value}
            disabled={option.disabled}
          >
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </SelectRoot>
  );
};

