import {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";

export interface ThemeProviderProps {
  children: ReactNode;
  /** Current theme tokens (CSS variable name → value). */
  tokens?: Record<string, string>;
  themeName?: string;
}

export interface ThemeContextValue {
  tokens: Record<string, string>;
  themeName: string | undefined;
}

const DEFAULT_CONTEXT: ThemeContextValue = {
  tokens: {},
  themeName: undefined,
};

const ThemeContext = createContext<ThemeContextValue>(DEFAULT_CONTEXT);

function applyTokens(tokens: Record<string, string>, target: HTMLElement) {
  for (const [key, value] of Object.entries(tokens)) {
    if (key.startsWith("--")) {
      target.style.setProperty(key, value);
    }
  }
}

function removeUnusedTokens(
  prevKeys: string[],
  newKeys: Set<string>,
  target: HTMLElement
) {
  for (const key of prevKeys) {
    if (!newKeys.has(key)) {
      target.style.removeProperty(key);
    }
  }
}

function removeAllTokens(keys: string[], target: HTMLElement) {
  for (const key of keys) {
    target.style.removeProperty(key);
  }
}

function resetTheme(
  prevTokenKeysRef: React.RefObject<string[]>,
  target: HTMLElement
) {
  removeAllTokens(prevTokenKeysRef.current, target);
  prevTokenKeysRef.current = [];
}

function ThemeProvider({ children, tokens, themeName }: ThemeProviderProps) {
  const prevTokenKeysRef = useRef<string[]>([]);

  useLayoutEffect(() => {
    const target = document.documentElement;

    if (!tokens) {
      // Head script already applied tokens and ThemeProvider hasn't taken over yet — don't reset
      if (
        prevTokenKeysRef.current.length === 0 &&
        document.body.hasAttribute("data-theme-ready")
      ) {
        // Fetch head-script tokens so they can be cleaned up later
        const headKeys: string[] = [];
        for (let i = 0; i < target.style.length; i++) {
          const prop = target.style.item(i);
          if (prop.startsWith("--")) {
            headKeys.push(prop);
          }
        }
        prevTokenKeysRef.current = headKeys;
        return;
      }

      if (prevTokenKeysRef.current.length > 0) {
        resetTheme(prevTokenKeysRef, target);
      }
      return;
    }

    const nextTokenKeys = Object.keys(tokens);
    removeUnusedTokens(
      prevTokenKeysRef.current,
      new Set(nextTokenKeys),
      target
    );
    applyTokens(tokens, target);
    prevTokenKeysRef.current = nextTokenKeys;
  }, [tokens]);

  // Clean up inline styles on unmount
  useEffect(() => {
    return () => {
      if (prevTokenKeysRef.current.length > 0) {
        resetTheme(prevTokenKeysRef, document.documentElement);
      }
    };
  }, []);

  const value = useMemo<ThemeContextValue>(
    () => ({
      tokens: tokens ?? {},
      themeName,
    }),
    [tokens, themeName]
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
}

function useTheme(): ThemeContextValue {
  return useContext(ThemeContext);
}

ThemeProvider.displayName = "ThemeProvider";

export { ThemeProvider, useTheme };
