import * as React from "react";
import { NumberField } from "@base-ui/react/number-field";
import { cn } from "../../lib/utils";

export interface NumberInputProps {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /**
   * Unit suffix to display after the number (e.g., "px", "s", "%")
   */
  suffix?: string;
  /**
   * Number of decimal places to show (defaults to 0 for integers, 1 for decimals)
   */
  decimals?: number;
  /**
   * Sensitivity multiplier for drag changes (default: 0.5)
   * Higher values = more sensitive (value changes faster per pixel of movement)
   */
  dragSensitivity?: number;
  /**
   * Text alignment (default: "center")
   */
  align?: "left" | "center";
  /**
   * Visual variant: "borderless" strips border/background so the input blends into a parent container
   */
  variant?: "default" | "error" | "borderless";
  className?: string;
  disabled?: boolean;
  placeholder?: string;
  id?: string;
}

/**
 * NumberInput with drag-to-change functionality
 *
 * @example
 * ```tsx
 * <NumberInput
 *   value={opacity}
 *   onChange={setOpacity}
 *   min={0}
 *   max={100}
 *   suffix="%"
 * />
 * ```
 */
export const NumberInput = React.forwardRef<HTMLInputElement, NumberInputProps>(
  (
    {
      value,
      onChange,
      min,
      max,
      step = 1,
      suffix = "",
      decimals,
      dragSensitivity = 0.5,
      align = "center",
      variant = "default",
      className,
      disabled,
      placeholder,
      id,
    },
    ref
  ) => {
    const [isEditing, setIsEditing] = React.useState(false);
    const [isDragging, setIsDragging] = React.useState(false);
    const localInputRef = React.useRef<HTMLInputElement>(null);
    const dragStartX = React.useRef(0);
    const dragStartValue = React.useRef(0);

    React.useImperativeHandle(ref, () => localInputRef.current!);

    const decimalPlaces = React.useMemo(() => {
      if (decimals !== undefined) return decimals;
      return step >= 1 ? 0 : 1;
    }, [decimals, step]);

    const formatOptions: Intl.NumberFormatOptions | undefined = React.useMemo(
      () => ({
        minimumFractionDigits: decimalPlaces,
        maximumFractionDigits: decimalPlaces,
      }),
      [decimalPlaces]
    );

    const handleValueChange = React.useCallback(
      (val: number | null) => {
        if (val !== null) {
          onChange(val);
        }
      },
      [onChange]
    );

    // Custom drag handler — absolute position from drag start with snap-to-step
    // Uses pointer capture so drag continues even when pointer leaves the iframe
    React.useEffect(() => {
      if (!isDragging) return;

      const handlePointerMove = (e: PointerEvent) => {
        const deltaX = e.clientX - dragStartX.current;
        const delta = deltaX * dragSensitivity * step;
        let newValue = dragStartValue.current + delta;
        newValue = Math.round(newValue / step) * step;
        newValue = Math.max(
          min ?? -Infinity,
          Math.min(max ?? Infinity, newValue)
        );
        onChange(newValue);
      };

      const handlePointerUp = (e: PointerEvent) => {
        (e.target as HTMLElement).releasePointerCapture?.(e.pointerId);
        setIsDragging(false);
        document.body.style.cursor = "";
      };

      window.addEventListener("pointermove", handlePointerMove);
      window.addEventListener("pointerup", handlePointerUp);
      return () => {
        window.removeEventListener("pointermove", handlePointerMove);
        window.removeEventListener("pointerup", handlePointerUp);
        document.body.style.cursor = "";
      };
    }, [isDragging, dragSensitivity, step, min, max, onChange]);

    const handlePointerDown = React.useCallback(
      (e: React.PointerEvent) => {
        if (disabled || isEditing) return;
        e.preventDefault();
        (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
        dragStartX.current = e.clientX;
        dragStartValue.current = value;
        setIsDragging(true);
        document.body.style.cursor = "ew-resize";
        localInputRef.current?.blur();
      },
      [disabled, isEditing, value]
    );

    const handleClick = React.useCallback(() => {
      if (!isDragging) {
        localInputRef.current?.focus();
      }
    }, [isDragging]);

    // Append suffix to the displayed value when not editing
    React.useLayoutEffect(() => {
      const input = localInputRef.current;
      if (!input || !suffix || isEditing) return;
      if (!input.value.endsWith(suffix)) {
        input.value = input.value + suffix;
      }
    });

    return (
      <NumberField.Root
        value={value}
        onValueChange={handleValueChange}
        min={min}
        max={max}
        step={step}
        disabled={disabled}
        format={formatOptions}
        className={cn("relative inline-flex items-center w-full", className)}
        id={id}
      >
        <NumberField.Input
          ref={localInputRef}
          placeholder={placeholder}
          aria-invalid={variant === "error" || undefined}
          onFocus={() => setIsEditing(true)}
          onBlur={() => setIsEditing(false)}
          onPointerDown={handlePointerDown}
          onClick={handleClick}
          className={cn(
            "h-6 w-full px-2 text-12 font-medium leading-tight",
            align === "left" ? "text-left" : "text-center",
            "text-foreground",
            variant === "borderless"
              ? "bg-transparent border-none rounded-none"
              : cn(
                  "bg-[color-mix(in_srgb,var(--border)_60%,transparent)]",
                  "border rounded-sm transition-colors",
                  variant === "error"
                    ? "border-destructive"
                    : "border-border hover:border-muted-foreground focus:border-ring"
                ),
            isDragging || !isEditing
              ? "cursor-ew-resize select-none"
              : "cursor-text",
            "focus:outline-hidden",
            "[&::selection]:bg-[color-mix(in_srgb,var(--ring)_50%,transparent)] [&::selection]:text-foreground",
            "disabled:opacity-50 disabled:cursor-not-allowed"
          )}
        />
      </NumberField.Root>
    );
  }
);

NumberInput.displayName = "NumberInput";
