import * as React from "react";
import { Switch } from "@base-ui/react/switch";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const toggleVariants = cva(
  "peer inline-flex shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "data-checked:bg-primary data-unchecked:bg-[color-mix(in_srgb,var(--secondary)_50%,transparent)]",
        error: "data-checked:bg-destructive data-unchecked:bg-[color-mix(in_srgb,var(--destructive)_20%,transparent)]",
      },
      size: {
        xs: "h-4 w-7",
        sm: "h-5 w-9",
        default: "h-6 w-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

const toggleThumbVariants = cva(
  "pointer-events-none block rounded-full bg-background shadow-lg ring-0 transition-transform data-unchecked:translate-x-0",
  {
    variants: {
      variant: {
        default: "",
        error: "",
      },
      size: {
        xs: "h-3 w-3 data-checked:translate-x-3",
        sm: "h-4 w-4 data-checked:translate-x-4",
        default: "h-5 w-5 data-checked:translate-x-5",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ToggleProps
  extends Omit<
    React.ComponentPropsWithoutRef<typeof Switch.Root>,
    "checked" | "defaultChecked" | "onCheckedChange"
  >,
  VariantProps<typeof toggleVariants> {
  /**
   * The controlled checked state of the toggle.
   */
  checked?: boolean;

  /**
   * The default checked state when uncontrolled.
   */
  defaultChecked?: boolean;

  /**
   * Callback fired when the checked state changes.
   */
  onCheckedChange?: (checked: boolean) => void;

  /**
   * Whether the toggle is disabled.
   */
  disabled?: boolean;

  /**
   * The visual variant of the toggle.
   * @default "default"
   */
  variant?: "default" | "error";

  /**
   * The size of the toggle.
   * @default "default"
   */
  size?: "xs" | "sm" | "default";

  /**
   * Optional aria-label for accessibility.
   * Required if no visible label is provided.
   */
  "aria-label"?: string;
}

/**
 * iOS-style toggle switch component
 * Built on Base UI Switch for full accessibility
 *
 * @example
 * ```tsx
 * // Uncontrolled
 * <Toggle defaultChecked aria-label="Enable notifications" />
 *
 * // Controlled
 * <Toggle
 *   checked={enabled}
 *   onCheckedChange={setEnabled}
 *   aria-label="Enable notifications"
 * />
 *
 * // Error state
 * <Toggle variant="error" aria-label="Invalid setting" />
 * ```
 */
const Toggle = React.forwardRef<
  HTMLElement,
  ToggleProps
>(({ className, variant, size, onCheckedChange, ...props }, ref) => (
  <Switch.Root
    className={cn(toggleVariants({ variant, size, className }))}
    aria-invalid={variant === "error" || undefined}
    onCheckedChange={onCheckedChange}
    {...props}
    ref={ref}
  >
    <Switch.Thumb className={cn(toggleThumbVariants({ variant, size }))} />
  </Switch.Root>
));
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
